drink", "station": "main", "food_type": "veg", "image_url": "https://ywylhzcxuoeilygzdonx.supabase.co/storage/v1/object/public/item-images/bd4d8ee9-5885-41e4-b6a1-ba2b9cb873dd/items/fe69414d-6971-4808-a52b-c373945a235c/86283b3f-270a-47b9-b815-3c0add29cb0a.jpg", "created_at": "2026-10-25T13:13:45.197432+00:00", "sort_order": 0, "updated_at": "2026-10-27T11:43:46.301903+00:00", "category_id": "3ec9757c-a3e3-4aea-afce-6ae3c9af9186", "description": "A sparkling, ocean-blue cooler of blue curaçao syrup, fresh lemon and chilled soda over ice, with fresh mint. Zesty, fizzy and alcohol-free.", "price_minor": 19900, "edit_version": 4, "is_available": true, "prep_minutes": 10, "currency_code": "INR", "is_recommended": false, "organization_id": "bd4d8ee9-5885-41e4-b6a1-ba2b9cb873dd"}, {"id": "350fb35e-c29a-4454-8c82-1589ecae4cda", "sku": null, "name": "Ice Mint Mocha", "price": 189.00, "course": "drink", "station": "main", "food_type": "veg", "image_url": "https://ywylhzcxuoeilygzdonx.supabase.co/storage/v1/object/public/item-images/bd4d8ee9-5885-41e4-b6a1-ba2b9cb873dd/items/350fb35e-c29a-4454-8c82-1589ecae4cda/b02682d6-793f-462d-a6bf-1d3d987ec558.jpg", "created_at": "2026-10-25T13:13:45.197432+00:00", "sort_order": 0, "updated_at": "2026-10-27T11:43:46.301903+00:00", "category_id": "3ec9757c-a3e3-4aea-afce-6ae3c9af9186", "description": "Espresso, chilled milk and rich chocolate with a cool hint of mint, poured over ice and crowned with whipped cream. Refreshing and indulgent.", "price_minor": 18900, "edit_version": 4, "is_available": true, "prep_minutes": 10, "currency_code": "INR", "is_recommended": false, "organization_id": "bd4d8ee9-5885-41e4-b6a1-ba2b9cb873dd"}, {"id": "94ce1d69-636f-49bf-b294-6414232dd89f", "sku": null, "name": "Paneer Subway", "price": 209.00, "course": "eat", "station": "main", "food_type": "veg", "image_url": "https://ywylhzcxuoeilygzdonx.supabase.co/storage/v1/object/public/item-images/bd4d8ee9-5885-41e4-b6a1-ba2b9cb873dd/items/94ce1d69-636f-49bf-b29